FROM NHS_HOS_APLY_REJ_RSN;

-- [SOURCE_QUALIFIER] Step: apply_SQ_NHS_HOS_APLY_REJ_RSN_END
select k.hos_aply_rej_rsn_key, ks.bgn_date
from sor_nhs_hos_aply_rej_rsn k, sor_nhs_hos_aply_rej_rsn_sts ks left join 
(select k.hos_aply_rej_rsn_key from nhs_hos_aply_rej_rsn p, sor_nhs_hos_aply a, sor_nhs_hos_aply_rej_rsn k
where p.hos_aply_key = a.nhs_hos_aply_key
  and k.hos_aply_key = a.hos_aply_key
  and p.rej_rsn_seq_num = k.nhs_rej_rsn_seq_num) e
on ks.hos_aply_rej_rsn_key = e.hos_aply_rej_rsn_key
where k.hos_aply_rej_rsn_key = ks.hos_aply_rej_rsn_key and ks.end_date = date'9999-12-31'
and e.hos_aply_rej_rsn_key is null
and exists (select 1 from nhs_hos_aply_rej_rsn);

