-- [SOURCE_QUALIFIER] Step: apply_SQ_NHS_HOS_APLY_MBR_END
select k.hos_aply_mbr_key, ks.bgn_date
from sor_nhs_hos_aply_mbr k, sor_nhs_hos_aply_mbr_sts ks left join 
(select k.hos_aply_mbr_key from nhs_hos_aply_mbr p, sor_nhs_hos_aply a, sor_nhs_hos_aply_mbr k
where p.hos_aply_key = a.nhs_hos_aply_key
  and k.hos_aply_key = a.hos_aply_key
  and p.aply_mbr_seq_num = k.nhs_aply_mbr_seq_num) e
on ks.hos_aply_mbr_key = e.hos_aply_mbr_key
where k.hos_aply_mbr_key = ks.hos_aply_mbr_key and ks.end_date = date'9999-12-31'
and e.hos_aply_mbr_key is null
and exists (select 1 from nhs_hos_aply_mbr);

