SELECT NHS_HOS_APLY_MBR.HOS_APLY_KEY, NHS_HOS_APLY_MBR.APLY_MBR_SEQ_NUM, NHS_HOS_APLY_MBR.FORM_COLR_CODE, NHS_HOS_APLY_MBR.HOS_APLY_NUM, NHS_HOS_APLY_MBR.APLY_MBR_ID_TYPE_CODE, NHS_HOS_APLY_MBR.APLY_MBR_ID_NUM, NHS_HOS_APLY_MBR.APLY_MBR_ID_CERT_NUM, NHS_HOS_APLY_MBR.APLY_MBR_ENG_SRNM_NAME, NHS_HOS_APLY_MBR.APLY_MBR_ENG_GIVE_NAME, NHS_HOS_APLY_MBR.APLY_MBR_CHI_NAME, NHS_HOS_APLY_MBR.APLY_MBR_GNDR_CODE, NHS_HOS_APLY_MBR.APLY_MBR_DOB_TEXT, NHS_HOS_APLY_MBR.APLY_MBR_RLTN_CODE, NHS_HOS_APLY_MBR.APLY_MBR_RLTN_DESP, NHS_HOS_APLY_MBR.APLY_MBR_MRTL_STS_CODE, NHS_HOS_APLY_MBR.SPS_LAND_HK_RGHT_IND, NHS_HOS_APLY_MBR.PRGNT_OVER_16_WEEK_IND, NHS_HOS_APLY_MBR.MBR_OWNR_CODE, NHS_HOS_APLY_MBR.ROW_VER_NUM, NHS_HOS_APLY_MBR.LAST_REC_TXN_TYPE_CODE, NHS_HOS_APLY_MBR.LAST_REC_TXN_DATE, NHS_HOS_APLY_MBR.LAST_REC_TXN_USER_ID, NHS_HOS_APLY_MBR.APLY_MBR_HKIC_PRMNT_IND, NHS_HOS_APLY_MBR.EFAS_DBL_BNFT_IND 
