-- =============================================================================

-- [TABLE_READ] Step: read_NHS_HOS_APLY_CATG_PRIOR
-- Table: NHS_HOS_APLY
-- Connection: SSA
SELECT * FROM NHS_HOS_APLY;

-- [SOURCE_QUALIFIER] Step: apply_SQ_NHS_HOS_APLY_CATG_PRIOR_END
select k.hos_aply_prior_key, ks.bgn_date
from sor_nhs_hos_aply_prior k, sor_nhs_hos_aply_prior_sts ks left join 
(select /*+ ordered */ k.hos_aply_prior_key from nhs_hos_aply_catg_prior p, sor_nhs_hos_aply a, sor_nhs_hos_aply_prior k
where p.hos_aply_key = a.nhs_hos_aply_key
  and k.hos_aply_key = a.hos_aply_key
  and p.prior_catg_code = k.nhs_prior_catg_code) e
on ks.hos_aply_prior_key = e.hos_aply_prior_key
where k.hos_aply_prior_key = ks.hos_aply_prior_key and ks.end_date = date'9999-12-31'
and e.hos_aply_prior_key is null
and exists (select 1 from nhs_hos_aply_catg_prior);

